def write(f,key,text,kind='Texto'):
 inline(f,key,text,kind);return f.locator(f'[data-cell="{key}"]>.content-block').last.get_attribute('data-nid')
def card(f,id):return f.locator('[data-nid="'+id+'"].content-block')
